// 000001(A), 000010(B), 000100(C), 001000(D), 010000(E), 100000(F)
module TopModule(input [5:0] y, input w, output reg Y1, output reg Y3);
  reg [5:0] ns;
  always @(*) begin
    case (y)
      6'b000001: ns = w ? 6'b000010 : 6'b000001;
      6'b000010: ns = w ? 6'b000100 : 6'b000001;
      6'b000100: ns = w ? 6'b001000 : 6'b000010;
      6'b001000: ns = w ? 6'b010000 : 6'b000010;
      6'b010000: ns = w ? 6'b100000 : 6'b000100;
      6'b100000: ns = w ? 6'b000001 : 6'b000100;
      default: ns = 6'b000001;
    endcase
  end
  always @(posedge ns[0]) Y1 <= 1;
  always @(posedge ns[2]) Y3 <= 1;
  always @(posedge ns[0], posedge ns[2]) Y1 <= 0;
  always @(posedge ns[2], posedge ns[0]) Y3 <= 0;
endmodule

